import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { api, API_BASE } from "../utils/api";

export default function Portal() {
  const [loading, setLoading] = useState(true);
  const [cases, setCases] = useState([]);

  // New report form states
  const [submitting, setSubmitting] = useState(false);
  const [category, setCategory] = useState("WHATSAPP");
  const [message, setMessage] = useState("");
  const [suspectNumber, setSuspectNumber] = useState("");
  const [link, setLink] = useState("");
  const [screenshot, setScreenshot] = useState(null);

  function getTokenOrRedirect() {
    const token = localStorage.getItem("user_token");
    if (!token) {
      window.location.href = "/login";
      return null;
    }
    return token;
  }

  async function loadMyCases() {
    const token = getTokenOrRedirect();
    if (!token) return;

    const res = await api.get("/api/portal/my-cases", {
      headers: { Authorization: `Bearer ${token}` }
    });

    setCases(res.data || []);
  }

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        await loadMyCases();
      } finally {
        setLoading(false);
      }
    })();
    // eslint-disable-next-line
  }, []);

  function logout() {
    localStorage.removeItem("user_token");
    localStorage.removeItem("user_profile");
    window.location.href = "/";
  }

  async function submitCase(e) {
    e.preventDefault();

    const token = getTokenOrRedirect();
    if (!token) return;

    if (!message.trim()) {
      alert("Please enter your message");
      return;
    }

    setSubmitting(true);
    try {
      const form = new FormData();
      form.append("category", category);
      form.append("message", message);
      form.append("suspectNumber", suspectNumber);
      form.append("link", link);

      if (screenshot) {
        form.append("screenshot", screenshot);
      }

      await api.post("/api/portal/report", form, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data"
        }
      });

      // reset form
      setCategory("WHATSAPP");
      setMessage("");
      setSuspectNumber("");
      setLink("");
      setScreenshot(null);

      alert("Report submitted ✅");

      // reload cases
      await loadMyCases();
    } catch (err) {
      console.log(err);
      alert("Failed to submit report ❌");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />

      <div className="max-w-5xl mx-auto px-4 py-10">
        <div className="flex justify-between items-center gap-4">
          <div>
            <h1 className="text-4xl font-black">My Portal</h1>
            <p className="text-gray-600 mt-1">
              Track your scam reports and SOC reply.
            </p>
          </div>

          <button
            onClick={logout}
            className="px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold"
          >
            Logout
          </button>
        </div>

        {/* REPORT FORM */}
        <div className="mt-8 bg-white rounded-3xl shadow p-6 border">
          <div className="text-2xl font-black">Report a Scam</div>
          <p className="text-gray-600 mt-1 text-sm">
            Submit details and screenshot (optional). SOC will reply here.
          </p>

          <form onSubmit={submitCase} className="mt-5 space-y-4">
            <div>
              <div className="text-sm font-semibold mb-2">Category</div>
              <select
                className="w-full border rounded-2xl px-4 py-3 bg-white"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
              >
                <option value="WHATSAPP">WHATSAPP</option>
                <option value="CALL">CALL</option>
                <option value="SMS">SMS</option>
                <option value="UPI">UPI</option>
                <option value="BANK">BANK</option>
                <option value="EMAIL">EMAIL</option>
                <option value="WEBSITE">WEBSITE</option>
                <option value="OTHER">OTHER</option>
              </select>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">Your Message *</div>
              <textarea
                className="w-full border rounded-2xl px-4 py-3 min-h-[120px]"
                placeholder="Explain what happened..."
                value={message}
                onChange={(e) => setMessage(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <div className="text-sm font-semibold mb-2">
                  Suspect Number (optional)
                </div>
                <input
                  className="w-full border rounded-2xl px-4 py-3"
                  placeholder="e.g. 9876543210"
                  value={suspectNumber}
                  onChange={(e) => setSuspectNumber(e.target.value)}
                />
              </div>

              <div>
                <div className="text-sm font-semibold mb-2">
                  Link (optional)
                </div>
                <input
                  className="w-full border rounded-2xl px-4 py-3"
                  placeholder="Paste scam link if any"
                  value={link}
                  onChange={(e) => setLink(e.target.value)}
                />
              </div>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">
                Screenshot (optional)
              </div>
              <input
                type="file"
                accept="image/png,image/jpeg,image/webp"
                onChange={(e) => setScreenshot(e.target.files?.[0] || null)}
              />

              {screenshot && (
                <div className="text-xs text-gray-600 mt-2">
                  Selected: <b>{screenshot.name}</b>
                </div>
              )}
            </div>

            <button
              disabled={submitting}
              className="px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold w-full"
            >
              {submitting ? "Submitting..." : "Submit Report"}
            </button>
          </form>
        </div>

        {/* MY CASES */}
        <div className="mt-10">
          <div className="text-2xl font-black">My Reports</div>
          <p className="text-gray-600 mt-1 text-sm">
            Your submitted reports will appear here.
          </p>

          {loading ? (
            <div className="mt-6 text-gray-600">Loading...</div>
          ) : (
            <div className="mt-6 space-y-4">
              {cases.map((c) => (
                <div
                  key={c._id}
                  className="bg-white rounded-3xl shadow p-6 border"
                >
                  <div className="flex justify-between items-center gap-4">
                    <div className="font-black text-xl">{c.ticketId}</div>
                    <div className="text-xs font-bold">
                      {c.status} • {c.severity}
                    </div>
                  </div>

                  <div className="text-sm text-gray-600 mt-1">
                    {new Date(c.createdAt).toLocaleString()}
                  </div>

                  <div className="mt-4 text-sm">
                    <b>Your Message:</b>
                    <div className="mt-2 whitespace-pre-wrap text-gray-800">
                      {c.message}
                    </div>
                  </div>

                  {c.suspectNumber && (
                    <div className="text-sm mt-3">
                      <b>Suspect Number:</b> {c.suspectNumber}
                    </div>
                  )}

                  {c.link && (
                    <div className="text-sm mt-2">
                      <b>Link:</b>{" "}
                      <a
                        href={c.link}
                        target="_blank"
                        rel="noreferrer"
                        className="text-blue-600 underline"
                      >
                        {c.link}
                      </a>
                    </div>
                  )}

                  {c.analystReply && (
                    <div className="mt-5 border rounded-2xl p-4 bg-gray-50">
                      <div className="font-black text-lg">SOC Reply</div>
                      <div className="mt-2 whitespace-pre-wrap text-gray-800">
                        {c.analystReply}
                      </div>
                    </div>
                  )}

                  {c.screenshotUrl ? (
                    <div className="mt-5">
                      <div className="font-semibold text-sm">Screenshot</div>

                      <img
                         alt="screenshot"
                         
                        alt="screenshot"
                        className="mt-2 rounded-2xl border max-h-[260px]"
                      />
                    </div>
                  ) : (
                    <div className="mt-5 text-sm text-gray-500">
                      No screenshot uploaded.
                    </div>
                  )}
                </div>
              ))}

              {cases.length === 0 && (
                <div className="text-gray-600 mt-4">No cases yet.</div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
